#[test]
fn metadata_phase_precharges_work_edges_and_derived_copies() {
    let input = bytes("storage");
    let ctx = context(&input);
    let mut full = Budget::new(&Limits::default());
    let types = crate::execution::verify_types(&ctx, &mut full).unwrap();
    let abi = crate::abi::verify(&ctx, &types, &mut full).unwrap();
    for limits in [
        Limits {
            max_semantic_work: 0,
            ..Limits::default()
        },
        Limits {
            max_graph_edges: 0,
            ..Limits::default()
        },
        Limits {
            max_derived_bytes: 0,
            ..Limits::default()
        },
    ] {
        let error = match crate::metadata::verify(&ctx, &types, &abi, &mut Budget::new(&limits)) {
            Err(error) => error,
            Ok(_) => panic!("exhausted metadata budget issued facts"),
        };
        assert_eq!(error.class(), ErrorClass::Resource);
    }
}

#[test]
fn actual_local_journal_and_external_recipe_retain_distinct_obligations() {
    let input = bytes("external-cleanup-journal");
    let ctx = context(&input);
    let mut budget = Budget::new(&Limits::default());
    let types = crate::execution::verify_types(&ctx, &mut budget).unwrap();
    let abi = crate::abi::verify(&ctx, &types, &mut budget).unwrap();
    let metadata = crate::metadata::verify(&ctx, &types, &abi, &mut budget).unwrap();
    let program =
        crate::execution::verify_program(&ctx, &types, &abi, &metadata, &mut budget).unwrap();
    crate::metadata::verify_program_joins(&ctx, &types, &abi, &metadata, &program, &mut budget)
        .unwrap();
    assert_eq!(
        program.requirements(),
        &[
            crate::execution::ProgramRequirement::ExternalCleanupRecipe {
                function: 1,
                action: 0,
                slot: 0,
                declaration: 9
            }
        ]
    );
    assert!(
        metadata
            .requirements()
            .obligations()
            .contains(&RuntimeRequirement::Dependency { slot: 0 })
    );
    let journal = ctx.local(crate::context::Namespace::Journal, 0).unwrap();
    assert!(abi.journal(journal).is_ok());
    assert!(ctx.local(crate::context::Namespace::Recipe, 9).is_err());
    assert!(ctx.declaration(0, 9).is_ok());
    crate::verify_object(&input, Limits::default()).unwrap();
}

//! All helper catalog templates at the type/option subphases only.
//! ABI/target/registration joins and whole MetadataFacts remain separate gates.
use crate::metadata::imports::{Catalogs, verify_helper_types, verify_options_with_abi};
use crate::{
    ErrorClass, Limits, RecordValue,
    context::{Namespace, ObjectContext, field, list},
    limits::Budget,
};
use std::collections::{BTreeMap, BTreeSet};

fn set(record: &mut RecordValue, key: &str, value: RecordValue) {
    let RecordValue::Record(fields) = record else {
        panic!("record")
    };
    fields.insert(key.to_owned(), value);
}
fn reference(id: u64) -> RecordValue {
    RecordValue::Record(BTreeMap::from([
        (
            "module".into(),
            RecordValue::Record(BTreeMap::from([(
                "kind".into(),
                RecordValue::Text("self".into()),
            )])),
        ),
        ("id".into(), RecordValue::Unsigned(id)),
    ]))
}

#[test]
fn every_helper_contract_has_actual_type_and_option_predicate_witnesses() {
    let manifest: serde_json::Value =
        serde_json::from_str(include_str!("helper-catalog-fixtures/manifest.json")).unwrap();
    let folder = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/metadata/helper-catalog-fixtures");
    let catalogs = Catalogs::load(&mut Budget::new(&Limits::default())).unwrap();
    let mut names = BTreeSet::new();
    let mut count = 0;
    for (label, case) in manifest["cases"].as_object().unwrap() {
        let data = std::fs::read(folder.join(format!("{label}.smo"))).unwrap();
        let mut budget = Budget::new(&Limits::default());
        let ctx = ObjectContext::new(
            crate::decode_object(&data, Limits::default()).unwrap(),
            &mut budget,
        )
        .unwrap();
        let types = crate::execution::verify_types(&ctx, &mut budget).unwrap();
        let abi = crate::abi::verify(&ctx, &types, &mut budget).unwrap();
        let record = &list(field(ctx.root(6).unwrap(), "imports").unwrap()).unwrap()[0];
        let name = case["name"].as_str().unwrap();
        let spec = catalogs.helper(name).unwrap();
        verify_helper_types(&ctx, &types, record, spec, &mut budget)
            .unwrap_or_else(|e| panic!("{label}: {e:?}"));
        let binding = abi
            .storage_binding(ctx.local(Namespace::StorageBinding, 1).unwrap())
            .unwrap();
        verify_options_with_abi(record, spec, Some(binding), &mut budget)
            .unwrap_or_else(|e| panic!("{label}: {e:?}"));
        // Mutation inputs remain untrusted standalone records, checked against
        // real immutable TypeFacts. They do not issue any object-phase proof.
        let mut non_function = record.clone();
        set(&mut non_function, "signature", reference(1));
        let error =
            verify_helper_types(&ctx, &types, &non_function, spec, &mut budget).unwrap_err();
        assert_eq!(error.class(), ErrorClass::Semantic);
        assert_eq!(error.code(), "RT_HELPER_SIGNATURE");
        let mut extra = record.clone();
        let RecordValue::Vector(mut args) = field(record, "types").unwrap().clone() else {
            panic!()
        };
        args.push(reference(1));
        set(&mut extra, "types", RecordValue::Vector(args));
        assert_eq!(
            verify_helper_types(&ctx, &types, &extra, spec, &mut budget)
                .unwrap_err()
                .code(),
            "RT_HELPER_TYPE_ARITY"
        );
        let mut invalid = record.clone();
        let mut options = field(record, "options").unwrap().clone();
        set(&mut options, "alignment", RecordValue::Unsigned(0));
        set(&mut invalid, "options", options);
        assert_eq!(
            verify_options_with_abi(&invalid, spec, Some(binding), &mut budget)
                .unwrap_err()
                .code(),
            "RT_HELPER_ALIGNMENT"
        );
        names.insert(name.to_owned());
        count += 1;
    }
    assert_eq!(names.len(), 177);
    assert_eq!(count, 368);
}

use crate::metadata::imports::{Catalogs, verify_options};
use crate::{Limits, limits::Budget, wire::RecordValue as V};
use std::collections::BTreeMap;

fn record(contract: &str) -> V {
    V::Record(BTreeMap::from([
        ("contract".into(), V::Text(contract.into())),
        (
            "options".into(),
            V::Record(BTreeMap::from([
                ("alignment".into(), V::Unsigned(1)),
                ("scope".into(), V::Text("process".into())),
                ("order".into(), V::Text("none".into())),
                ("failure_order".into(), V::Text("none".into())),
                ("weak".into(), V::Boolean(false)),
                ("comparison".into(), V::Text("none".into())),
                ("mask".into(), V::Bytes(vec![])),
                ("rounding".into(), V::Text("none".into())),
                ("exceptions".into(), V::Text("none".into())),
                ("predicate".into(), V::Text("none".into())),
                ("target".into(), V::Option(None)),
                ("flags".into(), V::Vector(vec![])),
            ])),
        ),
    ]))
}
fn option(value: &mut V, key: &str, replacement: V) {
    let V::Record(r) = value else { panic!() };
    let V::Record(options) = r.get_mut("options").unwrap() else {
        panic!()
    };
    options.insert(key.into(), replacement);
}
fn text(value: &str) -> V {
    V::Text(value.into())
}

#[test]
fn catalog_digests_match_independent_python_receipts() {
    let catalogs = Catalogs::load(&mut Budget::new(&Limits::default())).unwrap();
    let hex = |bytes: [u8; 32]| bytes.iter().map(|b| format!("{b:02x}")).collect::<String>();
    assert_eq!(
        hex(catalogs.helper_digest()),
        "56cf1e07ba5256a958c27fcdce5b013f09a3e27552d0d1e3e579f33035643988"
    );
    assert_eq!(
        hex(catalogs.service_digest()),
        "7cbbc87ceb70207fbc59dfe3fa3882d8ea50c8c9d1cf39c585d3b1c8780c15d6"
    );
    assert!(catalogs.helper("unknown").is_err());
    assert!(catalogs.service("memory.map").is_ok());
    assert!(catalogs.service("memory.load").is_err());
}

#[test]
fn memory_options_and_duplicate_flags() {
    let mut budget = Budget::new(&Limits::default());
    let catalogs = Catalogs::load(&mut budget).unwrap();
    let spec = catalogs.helper("memory_load").unwrap();
    let mut value = record("ordinary");
    option(&mut value, "alignment", V::Unsigned(8));
    option(&mut value, "flags", V::Vector(vec![text("volatile")]));
    verify_options(&value, spec, None, &mut budget).unwrap();
    option(
        &mut value,
        "flags",
        V::Vector(vec![text("volatile"), text("volatile")]),
    );
    assert_eq!(
        verify_options(&value, spec, None, &mut budget)
            .unwrap_err()
            .code(),
        "RT_HELPER_FLAGS"
    );
    option(&mut value, "flags", V::Vector(vec![text("elementwise")]));
    assert_eq!(
        verify_options(&value, spec, None, &mut budget)
            .unwrap_err()
            .code(),
        "RT_HELPER_ELEMENTWISE_POLICY"
    );
}

#[test]
fn atomic_compare_failure_order_and_mask_require_actual_binding() {
    let mut budget = Budget::new(&Limits::default());
    let catalogs = Catalogs::load(&mut budget).unwrap();
    let spec = catalogs.helper("atomic_cmpxchg").unwrap();
    let mut value = record("value_mask");
    option(&mut value, "order", text("seq_cst"));
    option(&mut value, "failure_order", text("acquire"));
    option(&mut value, "comparison", text("value_mask"));
    assert_eq!(
        verify_options(&value, spec, None, &mut budget)
            .unwrap_err()
            .code(),
        "RT_HELPER_ABI_MASK"
    );
    verify_options(&value, spec, Some(&[0xff, 0x01]), &mut budget).unwrap();
    option(&mut value, "mask", V::Bytes(vec![0xff, 0xff]));
    assert_eq!(
        verify_options(&value, spec, Some(&[0xff, 0x01]), &mut budget)
            .unwrap_err()
            .code(),
        "RT_HELPER_ABI_MASK"
    );
    option(&mut value, "mask", V::Bytes(vec![]));
    option(&mut value, "failure_order", text("release"));
    assert_eq!(
        verify_options(&value, spec, Some(&[]), &mut budget)
            .unwrap_err()
            .code(),
        "RT_HELPER_FAILURE_ORDER"
    );
}

#[test]
fn floating_context_predicate_and_fixed_rounding() {
    let mut budget = Budget::new(&Limits::default());
    let catalogs = Catalogs::load(&mut budget).unwrap();
    let mut value = record("constrained");
    assert_eq!(
        verify_options(
            &value,
            catalogs.helper("fp_add").unwrap(),
            None,
            &mut budget
        )
        .unwrap_err()
        .code(),
        "RT_HELPER_FP_CONTEXT"
    );
    option(&mut value, "rounding", text("dynamic"));
    option(&mut value, "exceptions", text("strict"));
    verify_options(
        &value,
        catalogs.helper("fp_add").unwrap(),
        None,
        &mut budget,
    )
    .unwrap();
    assert_eq!(
        verify_options(
            &value,
            catalogs.helper("fp_compare").unwrap(),
            None,
            &mut budget
        )
        .unwrap_err()
        .code(),
        "RT_HELPER_PREDICATE"
    );
    option(&mut value, "predicate", text("oeq"));
    verify_options(
        &value,
        catalogs.helper("fp_compare").unwrap(),
        None,
        &mut budget,
    )
    .unwrap();
    option(&mut value, "predicate", text("none"));
    assert_eq!(
        verify_options(
            &value,
            catalogs.helper("fp_lround").unwrap(),
            None,
            &mut budget
        )
        .unwrap_err()
        .code(),
        "RT_HELPER_ROUND_FIXED"
    );
    option(&mut value, "rounding", text("nearest_away"));
    verify_options(
        &value,
        catalogs.helper("fp_lround").unwrap(),
        None,
        &mut budget,
    )
    .unwrap();
}

