//! Actual generator/input/object hashes and non-writing byte-exact reproduction.
use sha2::{Digest, Sha256};
fn hash(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .map(|v| format!("{v:02x}"))
        .collect()
}
#[test]
fn all_owned_generated_corpora_have_reproducible_provenance_and_size_accounts() {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .unwrap()
        .parent()
        .unwrap();
    for folder in [
        "fixtures",
        "profile-fixtures",
        "state-helper-fixtures",
        "service-fixtures",
        "helper-catalog-fixtures",
        "source-role-fixtures",
        "canonical-profile-fixtures",
        "eh-release-fixtures",
    ] {
        let directory = root
            .join("crates/smir-portable/tests/metadata")
            .join(folder);
        let manifest: serde_json::Value =
            serde_json::from_slice(&std::fs::read(directory.join("manifest.json")).unwrap())
                .unwrap();
        let provenance = &manifest["provenance"];
        let generator = provenance["generator"].as_str().unwrap();
        assert!(generator.starts_with("crates/smir-portable/tests/metadata/"));
        assert_eq!(
            hash(&std::fs::read(root.join(generator)).unwrap()),
            provenance["generator_sha256"].as_str().unwrap()
        );
        for (relative, expected) in provenance["input_sha256"].as_object().unwrap() {
            assert!(!std::path::Path::new(relative).is_absolute());
            assert!(!relative.split('/').any(|v| v == ".."));
            assert_eq!(
                hash(&std::fs::read(root.join(relative)).unwrap()),
                expected.as_str().unwrap(),
                "{folder}: {relative}"
            );
        }
        let mut size = 0u64;
        for (name, case) in manifest["cases"].as_object().unwrap() {
            let data = std::fs::read(directory.join(format!("{name}.smo"))).unwrap();
            assert_eq!(
                hash(&data),
                case["sha256"].as_str().unwrap(),
                "{folder}/{name}"
            );
            assert_eq!(data.len() as u64, case["bytes"].as_u64().unwrap());
            size += data.len() as u64;
        }
        assert_eq!(size, provenance["encoded_object_bytes"].as_u64().unwrap());
        assert_eq!(
            manifest["cases"].as_object().unwrap().len() as u64,
            provenance["object_count"].as_u64().unwrap()
        );
        assert!(
            !provenance["size_justification"]
                .as_str()
                .unwrap()
                .is_empty()
        );
        let result = std::process::Command::new("python3")
            .arg("-B")
            .arg(root.join(generator))
            .arg("--check")
            .output()
            .unwrap();
        assert!(
            result.status.success(),
            "{folder}: {}{}",
            String::from_utf8_lossy(&result.stdout),
            String::from_utf8_lossy(&result.stderr)
        );
    }
}

use crate::Limits;
use crate::limits::Budget;
use crate::metadata::records::{
    PatchInterval, StorageKind, StorageView, ZeroShadow, reject_overlaps,
};
use crate::wire::RecordValue as V;
use std::collections::BTreeMap;

fn segment(initial: &[u8], poison: &[u8], undef: &[u8], zero_fill: u64, shadow: &str) -> V {
    V::Record(BTreeMap::from([
        ("id".into(), V::Unsigned(7)),
        ("alignment".into(), V::Unsigned(8)),
        ("mutable".into(), V::Boolean(false)),
        ("initial".into(), V::Bytes(initial.to_vec())),
        ("poison".into(), V::Bytes(poison.to_vec())),
        ("undef".into(), V::Bytes(undef.to_vec())),
        ("zero_fill".into(), V::Unsigned(zero_fill)),
        ("zero_shadow".into(), V::Text(shadow.into())),
    ]))
}

#[test]
fn symbolic_tail_and_clipped_shadow_ranges() {
    let record = segment(
        &[1, 2, 3],
        &[0, 0, 0],
        &[0, 0, 0],
        (1_u64 << 61) - 4,
        "defined",
    );
    let mut budget = Budget::new(&Limits::default());
    let storage = StorageView::parse(&record, &mut budget).unwrap();
    assert_eq!(storage.extent, (1_u64 << 61) - 1);
    let range = storage.range(1, 5).unwrap();
    assert_eq!(range.initial, &[2, 3]);
    assert_eq!(range.zero_tail_bytes, 3);
    assert_eq!(range.zero_tail_shadow, ZeroShadow::Defined);
    let range = storage.range(storage.extent, 0).unwrap();
    assert!(range.initial.is_empty());
    assert_eq!(range.zero_tail_bytes, 0);
    assert!(storage.range(storage.extent, 1).is_err());
    assert!(storage.range(u64::MAX, 1).is_err());
    assert!(storage.fully_defined_readonly(&mut budget).unwrap());
}

#[test]
fn shadow_conflict_and_length_mismatch_reject() {
    for record in [
        segment(&[1], &[], &[0], 0, "defined"),
        segment(&[1], &[1], &[1], 0, "defined"),
    ] {
        let mut budget = Budget::new(&Limits::default());
        assert_eq!(
            StorageView::parse(&record, &mut budget).unwrap_err().code(),
            "RT_SEGMENT_SHADOW"
        );
    }
}

#[test]
fn undefined_tail_is_not_native_metadata() {
    for shadow in ["poison", "undef"] {
        let record = segment(&[], &[], &[], 1_u64 << 61, shadow);
        let mut budget = Budget::new(&Limits::default());
        let storage = StorageView::parse(&record, &mut budget).unwrap();
        assert!(!storage.fully_defined_readonly(&mut budget).unwrap());
        let range = storage.range(123, 1000).unwrap();
        assert!(range.initial.is_empty());
        assert_eq!(range.zero_tail_bytes, 1000);
    }
}

