fn leaf(kind: &str, width: u64, bits: u64, check_base: bool, flags: &[&str]) -> V {
    V::Record(BTreeMap::from([
        ("kind".into(), V::Text(kind.into())),
        ("width".into(), V::Unsigned(width)),
        ("integer_bits".into(), V::Unsigned(bits)),
        ("derivation".into(), V::Vector(vec![])),
