//! Static binding proofs and actual malformed-unused-import rejection.
use crate::{ErrorClass, Limits};

#[test]
fn independent_state_helper_objects_and_unused_mutations_use_real_factory() {
    let manifest: serde_json::Value =
        serde_json::from_str(include_str!("state-helper-fixtures/manifest.json")).unwrap();
    let folder = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/metadata/state-helper-fixtures");
    let mut positive = 0;
    let mut negative = 0;
    let mut unknown = 0;
    for (name, case) in manifest["cases"].as_object().unwrap() {
        let data = std::fs::read(folder.join(format!("{name}.smo"))).unwrap();
        let result = crate::verify_object(&data, Limits::default());
        if case["accept"] == true {
            assert!(result.is_ok(), "{name}: {:?}", result.err());
            println!("state-helper {name}: static-verified");
            positive += 1;
        } else if case["expected_class"] == "unavailable-evidence" {
            let error = result
                .err()
                .unwrap_or_else(|| panic!("unaudited source issued facts: {name}"));
            assert_eq!(
                error.class(),
                ErrorClass::UnavailableEvidence,
                "{name}: {error:?}"
            );
            println!("state-helper {name}: unavailable {}", error.code());
            unknown += 1;
        } else {
            let error = result
                .err()
                .unwrap_or_else(|| panic!("malformed unused {name} accepted"));
            assert_eq!(error.class(), ErrorClass::Semantic, "{name}: {error:?}");
            println!("state-helper {name}: semantic {}", error.code());
            negative += 1;
        }
    }
    assert_eq!(positive, 15);
    assert_eq!(unknown, 0);
    assert!(
        negative == 75,
        "all supported-source mutations remain semantic, without fake record facts"
    );
}

use crate::context::{ContextId, EntityRef, ModuleRef, Namespace, ObjectContext};
use crate::metadata::storage::{DeclaredMetadataRange, declared_metadata_range, static_raw_range};
use crate::{Limits, decode_object, limits::Budget, wire::RecordValue as V};
use std::collections::BTreeMap;

fn context(input: &[u8]) -> ObjectContext {
    let object = decode_object(input, Limits::default()).unwrap();
    ObjectContext::new(object, &mut Budget::new(&Limits::default())).unwrap()
}
fn reference(module: ModuleRef, id: u32) -> V {
    let fields = match module {
        ModuleRef::SelfModule => BTreeMap::from([("kind".into(), V::Text("self".into()))]),
        ModuleRef::Dependency { slot } => BTreeMap::from([
            ("kind".into(), V::Text("dependency".into())),
            ("slot".into(), V::Unsigned(slot.into())),
        ]),
    };
    V::Record(BTreeMap::from([
        ("module".into(), V::Record(fields)),
        ("id".into(), V::Unsigned(id.into())),
    ]))
}

#[test]
fn direct_metadata_raw_hash_keeps_patch_obligation() {
    let ctx = context(include_bytes!("fixtures/base.smo"));
    let mut budget = Budget::new(&Limits::default());
    let DeclaredMetadataRange::Local(bytes) = declared_metadata_range(
        &ctx,
        &reference(ModuleRef::SelfModule, 1),
        1,
        3,
        &mut budget,
    )
    .unwrap() else {
        panic!()
    };
    assert_eq!(bytes.bytes().initial, &[2, 3]);
    assert_eq!(bytes.bytes().zero_tail_bytes, 1);
    assert_eq!(
        bytes.source(),
        Some(EntityRef {
            module: ModuleRef::SelfModule,
            id: 1
        })
    );
    assert_eq!(bytes.offset(), 1);
    assert_eq!(bytes.length(), 3);
    assert_eq!(bytes.identity(), ctx.identity());
    assert_eq!(bytes.context_id(), ctx.context_id());
    assert_eq!(bytes.patches().len(), 1);
    let digest = bytes.sha256(&mut budget).unwrap();
    assert_eq!(
        digest
            .iter()
            .map(|v| format!("{v:02x}"))
            .collect::<String>(),
        "01ac26723cbcba804b62c46419db1c078912c2905c421b5be95ed5b3523cb78b"
    );
    assert!(!bytes.mutable());
}

